import{_ as a,c as e,o,b0 as r}from"./chunks/framework.C5ev1SXp.js";const d="/scm-docs/assets/gateway-routing.DHEzNqGb.svg",u=JSON.parse('{"title":"LV015-网关与跨网段通信","description":null,"frontmatter":{"title":"LV015-网关与跨网段通信","date":"2026-10-14T21:56:00.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-14T21:56:00.512Z","fulluuid":"267db3a1c4e84f0d9ab6e25c83f107a4","useduuid":"267db3a1c"}},"headers":[],"relativePath":"sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.md","filePath":"sdoc/30-进阶篇/05-网络基础/LV015-网关与跨网段通信.md","lastUpdated":1792231946000}'),n={name:"sdoc/advanced-chapter/network-basics/126d628e1bb0267db3a1c4e8.md"};function s(l,t,i,h,c,p){return o(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="lv015-网关与跨网段通信" tabindex="-1">LV015-网关与跨网段通信 <a class="header-anchor" href="#lv015-网关与跨网段通信" aria-label="Permalink to &quot;LV015-网关与跨网段通信&quot;">​</a></h1><h2 id="一、-网关的作用与配置前提" tabindex="-1">一、 网关的作用与配置前提 <a class="header-anchor" href="#一、-网关的作用与配置前提" aria-label="Permalink to &quot;一、 网关的作用与配置前提&quot;">​</a></h2><h3 id="_1-什么是默认网关" tabindex="-1">1. 什么是默认网关 <a class="header-anchor" href="#_1-什么是默认网关" aria-label="Permalink to &quot;1. 什么是默认网关&quot;">​</a></h3><p>上一篇给出了两条转发规则，其中第二条是&quot;不同网段就交给网关&quot;。于是问题来了：<strong>网关到底是什么？</strong></p><p>一句话回答：<strong>默认网关是&quot;我不认识的目的地，统统先交给它&quot;的那台设备。</strong></p><p>它的本质是路由表里的一条特殊表项——目的网络是 <code>0.0.0.0/0</code>（能匹配任何地址）的<strong>默认路由</strong>：</p><table tabindex="0"><thead><tr><th>目的网络</th><th>掩码</th><th>下一跳</th></tr></thead><tbody><tr><td>192.168.16.0</td><td>/24</td><td>直连，不用下一跳</td></tr><tr><td>0.0.0.0</td><td>/0</td><td>192.168.16.1（默认网关）</td></tr></tbody></table><p>PC 上看到的&quot;默认网关&quot;输入框，填的就是这条默认路由的下一跳地址。</p><h3 id="_2-网关必须是同网段设备" tabindex="-1">2. 网关必须是同网段设备 <a class="header-anchor" href="#_2-网关必须是同网段设备" aria-label="Permalink to &quot;2. 网关必须是同网段设备&quot;">​</a></h3><p>这是配置网关时唯一的硬约束，理由还是&quot;要发帧就得先知道 MAC&quot;：</p><ul><li>要把包交给网关，就得把帧的目的 MAC 填成网关的 MAC；</li><li>要拿到网关的 MAC，就得对<strong>网关的 IP</strong> 发起 ARP；</li><li>ARP 只在本网段内广播——<strong>跨网段的地址是 ARP 不到的</strong>。</li></ul><p>所以 <code>192.168.16.30/24</code> 的板子，网关只能填 <code>192.168.16.1</code> ~ <code>192.168.16.254</code> 之间的地址。填一个 <code>192.168.1.1</code> 会直接导致&quot;网关不可达&quot;，所有跨网段的访问全部失败。</p><p>反过来看，这也解释了为什么<strong>同网段通信根本不看网关</strong>：直连场景里板子和 PC 互为&quot;直连路由&quot;，压根用不到默认路由。</p><h2 id="二、-路由表与最长前缀匹配" tabindex="-1">二、 路由表与最长前缀匹配 <a class="header-anchor" href="#二、-路由表与最长前缀匹配" aria-label="Permalink to &quot;二、 路由表与最长前缀匹配&quot;">​</a></h2><h3 id="_1-路由表长什么样" tabindex="-1">1. 路由表长什么样 <a class="header-anchor" href="#_1-路由表长什么样" aria-label="Permalink to &quot;1. 路由表长什么样&quot;">​</a></h3><p>路由器（以及每一台配了网关的主机）内部都有一张路由表，每条表项是&quot;目的网络 → 下一跳 / 出口&quot;：</p><table tabindex="0"><thead><tr><th>目的网络</th><th>下一跳</th><th>出口</th><th>类型</th></tr></thead><tbody><tr><td>192.168.16.0/24</td><td>直连</td><td>接口 A</td><td>直连路由</td></tr><tr><td>192.168.1.0/24</td><td>192.168.16.1</td><td>接口 A</td><td>静态/动态路由</td></tr><tr><td>0.0.0.0/0</td><td>运营商网关</td><td>接口 B</td><td>默认路由</td></tr></tbody></table><p>表里前两条说明了路由表的两种来源：接口配了地址就自动生成&quot;直连路由&quot;，其余靠手工配置（静态）或协议学习（动态，比如 RIP、OSPF）。</p><h3 id="_2-最长前缀匹配" tabindex="-1">2. 最长前缀匹配 <a class="header-anchor" href="#_2-最长前缀匹配" aria-label="Permalink to &quot;2. 最长前缀匹配&quot;">​</a></h3><p>当一个包要转发时，可能同时被多条表项匹配上，这时按<strong>最长前缀匹配</strong>（也叫最长掩码匹配）规则选择：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目的 IP = 192.168.16.30</span></span>
<span class="line"><span></span></span>
<span class="line"><span>候选 1: 192.168.16.0/24   前 24 位匹配 ✓</span></span>
<span class="line"><span>候选 2: 192.168.0.0/16    前 16 位匹配 ✓</span></span>
<span class="line"><span>候选 3: 0.0.0.0/0         匹配 ✓</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规则: 谁的掩码长（前缀长）就用谁  ⇒  选 192.168.16.0/24</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>这条规则的直觉解释是：<strong>掩码越长，描述的范围越小、越精确。</strong> 默认路由 <code>0.0.0.0/0</code> 前缀长度为 0，是所有表项里最&quot;偷懒&quot;的一条，所以它永远排在最后——只有前面积累的精确表项都匹配不上时才会用到。</p><h2 id="三、-跨网段转发时帧头发生了什么" tabindex="-1">三、 跨网段转发时帧头发生了什么 <a class="header-anchor" href="#三、-跨网段转发时帧头发生了什么" aria-label="Permalink to &quot;三、 跨网段转发时帧头发生了什么&quot;">​</a></h2><h3 id="_1-ip-头不变、以太网头逐跳重写" tabindex="-1">1. IP 头不变、以太网头逐跳重写 <a class="header-anchor" href="#_1-ip-头不变、以太网头逐跳重写" aria-label="Permalink to &quot;1. IP 头不变、以太网头逐跳重写&quot;">​</a></h3><p>这是理解路由器最关键的一点。路由器转发一个包时：</p><ul><li><strong>IP 头里的源 IP、目的 IP 全程不变</strong>（除了 NAT 这种特殊情况，见第四节）；</li><li><strong>以太网头被整个换掉</strong>：源 MAC 换成路由器自己出接口的 MAC，目的 MAC 换成下一跳的 MAC。</li></ul><p>对应到 TTL 字段，路由器还会把 TTL 减 1，减到 0 就丢弃并回 ICMP 超时报文——这是防止环路的基本保护。</p><table tabindex="0"><thead><tr><th>位置</th><th>目的 MAC</th><th>源 MAC</th><th>目的 IP</th><th>源 IP</th></tr></thead><tbody><tr><td>PC 发出的帧</td><td>网关</td><td>PC</td><td>板子</td><td>PC</td></tr><tr><td>路由器转发出的帧</td><td>板子</td><td>路由器接口 A</td><td>板子</td><td>PC</td></tr></tbody></table><img src="`+d+'" alt="跨网段转发时 MAC 逐跳重写、IP 全程不变"><h3 id="_2-用一次-ping-对照" tabindex="-1">2. 用一次 ping 对照 <a class="header-anchor" href="#_2-用一次-ping-对照" aria-label="Permalink to &quot;2. 用一次 ping 对照&quot;">​</a></h3><p>跨网段 ping 时（板子在 <code>192.168.16.0/24</code>、PC 在 <code>192.168.1.0/24</code>、中间是路由器）：</p><p>（1）PC 判断目的 IP 与自己<strong>不同网段</strong>，于是查默认路由，把帧发给自己网关的 MAC。</p><p>（2）PC 发起的 ARP 请求问的是<strong>网关的 MAC</strong>，而不是板子的 MAC——这一点最容易搞混。</p><p>（3）路由器收到帧，查路由表找到 <code>192.168.16.0/24</code> 直连，于是把帧从接口 A 发出去，<strong>换掉整个以太网头</strong>。</p><p>（4）板子收到请求，生成应答。目的 IP <code>192.168.1.100</code> 与自己不同网段，于是<strong>交给自己的网关</strong>——这一步要求板子<strong>必须配了正确的网关</strong>。</p><p>（5）路由器反向转发回 PC，链路两端的 MAC 再次被重写。</p><p>这里有一个非常有辨识度的故障现象：<strong>如果板子没配网关（或配了一个不存在的地址），它能收到请求却发不出应答</strong>。表现就是&quot;PC 一直超时，而板子串口日志显示确实收到了包&quot;。看到这个现象，不要怀疑收包路径，直接去查网关配置。</p><h2 id="四、-nat-私有地址为什么能重复使用" tabindex="-1">四、 NAT：私有地址为什么能重复使用 <a class="header-anchor" href="#四、-nat-私有地址为什么能重复使用" aria-label="Permalink to &quot;四、 NAT：私有地址为什么能重复使用&quot;">​</a></h2><h3 id="_1-出门换地址" tabindex="-1">1. 出门换地址 <a class="header-anchor" href="#_1-出门换地址" aria-label="Permalink to &quot;1. 出门换地址&quot;">​</a></h3><p><a href="/scm-docs/sdoc/advanced-chapter/network-basics/126d628e1bb0119ba6c38b7d.html">LV010</a> 提到过私有地址（<code>192.168.0.0/16</code> 等）可以重复使用，原因就是 <strong>NAT（网络地址转换）</strong>。</p><p>家用路由器 WAN 口拿到的是一个公网地址，内网设备包里的私有源地址在出门时会被换成这个公网地址：</p><table tabindex="0"><thead><tr><th>阶段</th><th>源 IP:端口</th><th>目的 IP:端口</th></tr></thead><tbody><tr><td>内网主机发出</td><td>192.168.16.30:50000</td><td>93.184.216.34:80</td></tr><tr><td>路由器 NAT 后</td><td>公网地址:40001</td><td>93.184.216.34:80</td></tr></tbody></table><h3 id="_2-回包怎么找回来" tabindex="-1">2. 回包怎么找回来 <a class="header-anchor" href="#_2-回包怎么找回来" aria-label="Permalink to &quot;2. 回包怎么找回来&quot;">​</a></h3><p>NAT 不只是替换地址，还要<strong>记住映射关系</strong>：路由器内部维护一张 NAT 表，记录&quot;公网地址:40001 ↔ 192.168.16.30:50000&quot;。回包到了公网地址的 40001 端口，按表换回私有地址与端口，再交给内网主机。</p><p>这解释了 NAT 的两个特征：</p><p>（1）<strong>内网可以随便用重复的私有地址</strong>，因为出门就被换掉了，公网上看到的只有路由器的公网地址。</p><p>（2）<strong>外网无法主动发起连接</strong>。外网设备不知道该用什么地址去连一台内网机器——NAT 表里没有对应表项就没有映射，包会被丢掉。这也是为什么网络升级实验里必须由 <strong>PC 主动去连板子</strong>，而不是板子反过来连 PC。</p><h2 id="五、-回到本工程-为什么本实验用不到网关" tabindex="-1">五、 回到本工程：为什么本实验用不到网关 <a class="header-anchor" href="#五、-回到本工程-为什么本实验用不到网关" aria-label="Permalink to &quot;五、 回到本工程：为什么本实验用不到网关&quot;">​</a></h2><h3 id="_1-直连与同交换机" tabindex="-1">1. 直连与同交换机 <a class="header-anchor" href="#_1-直连与同交换机" aria-label="Permalink to &quot;1. 直连与同交换机&quot;">​</a></h3><p>本工程的两种接法（网线直连、都接在同一台交换机上）都是<strong>同一个网段</strong>：</p><table tabindex="0"><thead><tr><th>角色</th><th>地址</th></tr></thead><tbody><tr><td>板子</td><td><code>192.168.16.30/24</code></td></tr><tr><td>PC</td><td><code>192.168.16.100/24</code></td></tr></tbody></table><p>两边互相访问走的是&quot;直连路由&quot;，<strong>默认路由一次都用不到</strong>。所以：</p><ul><li>网关填不填、填得对不对，都不影响 ping 与网络升级；</li><li>这也是为什么 <code>lwip_comm.h</code> 里把网关配成 <code>192.168.16.1</code> 只是一个&quot;备用值&quot;。</li></ul><h3 id="_2-网关填错的后果与排查" tabindex="-1">2. 网关填错的后果与排查 <a class="header-anchor" href="#_2-网关填错的后果与排查" aria-label="Permalink to &quot;2. 网关填错的后果与排查&quot;">​</a></h3><p>既然用不到，为什么还要提醒？因为<strong>填一个不存在的网关会引入假故障</strong>：</p><table tabindex="0"><thead><tr><th>现象</th><th>原因</th></tr></thead><tbody><tr><td>ping 板子正常，但 PC 访问别的网段失败</td><td>PC 的默认路由被指向了一个不存在的设备</td></tr><tr><td>PC 侧抓包看到 ICMP 重定向或&quot;目标主机不可达&quot;</td><td>网关存在但路由表里没有回程路由</td></tr><tr><td>板子能收到请求但不回应答</td><td>板子配了不通的网关，应答交给了默认路由</td></tr></tbody></table><p>排查建议只有一条：<strong>直连实验时把两边的网关留空</strong>。留空就没有默认路由，所有&quot;跨网段&quot;的访问会立刻以明确的错误失败，而不是卡在等待里。</p><h2 id="六、-小结与参考资料" tabindex="-1">六、 小结与参考资料 <a class="header-anchor" href="#六、-小结与参考资料" aria-label="Permalink to &quot;六、 小结与参考资料&quot;">​</a></h2><h3 id="_1-本篇小结" tabindex="-1">1. 本篇小结 <a class="header-anchor" href="#_1-本篇小结" aria-label="Permalink to &quot;1. 本篇小结&quot;">​</a></h3><ul><li>默认网关的本质是路由表里 <code>0.0.0.0/0</code> 这条默认路由的下一跳，PC 上的&quot;网关&quot;输入框填的就是它。</li><li>网关必须是同网段设备，因为要交给它就得先 ARP 到它的 MAC。</li><li>路由器选表项用<strong>最长前缀匹配</strong>：掩码越长越优先，默认路由永远垫底。</li><li>路由器转发时<strong>只改以太网头（逐跳重写 MAC）与 TTL，IP 源/目的地址全程不变</strong>。</li><li>NAT 让私有地址可以重复使用，同时导致&quot;外网无法主动连内网&quot;。</li><li>本工程的两种接法都在同一网段，用不到网关；直连实验建议两边网关留空，避免引入假故障。</li></ul><h3 id="_2-参考资料" tabindex="-1">2. 参考资料 <a class="header-anchor" href="#_2-参考资料" aria-label="Permalink to &quot;2. 参考资料&quot;">​</a></h3><ul><li>网络参数与静态网关：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/port/lwip_comm.h" target="_blank" rel="noreferrer"><code>lwip_comm.h</code></a></li><li>路由与地址对照：<a href="https://cnb.cool/smk.k/Microcontroller/bootloader/-/blob/main/atk-f103/Components/lwip-2.1.3/src/core/ipv4/ip4_addr.c" target="_blank" rel="noreferrer"><code>ip4_addr.c</code></a></li><li>实验中的实际接法：<a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a5205f2a80bf1e.html">LV020-网络通信实验</a> 第一节</li><li>手册：<a href="https://gitee.com/docs-site/scm-reference-guide/raw/main/30-STM32%E8%B5%84%E6%96%99/10-lwIP/STM32F1%20LWIP%E5%BC%80%E5%8F%91%E6%89%8B%E5%86%8C%28DM9000%E7%89%88%29_V1.1.pdf" target="_blank" rel="noreferrer"><code>STM32F1 LWIP开发手册(DM9000版)_V1.1.pdf</code></a> 第 1.3 节</li></ul><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',64)])])}const g=a(n,[["render",s]]);export{u as __pageData,g as default};
